const candidateName = $('Prompt Builder').item.json.candidate_name;
const aiQuestion = $('Generate Pertanyaan').item.json.text;

let mockAnswer;

if (candidateName.includes("Budi")) {
  // Skenario 1: jawaban teknis & mendalam
  mockAnswer = "Pertama saya cek kubectl describe pod dan kubectl logs --previous untuk melihat penyebab CrashLoopBackOff. " +
    "Lalu saya lihat metrik CPU/memory di Prometheus/Grafana, cek OOMKilled, resource limits, dan readiness probe. " +
    "Saya lakukan root cause analysis lewat korelasi log dan timeline deployment, cek drift pada state Terraform dan release Helm, " +
    "rollback jika perlu, lalu menambah alert dan menulis postmortem agar tidak terulang.";
} else {
  // Skenario 2: jawaban generik & dangkal
  mockAnswer = "Saya biasanya restart servernya pak. Kalau masih error saya install ulang Kubernetesnya.";
}

return {
  json: {
    question: aiQuestion,
    candidate_answer: mockAnswer,
    candidate_name: candidateName
  }
};

const data = $json;

const prompt = `
ROLE: You are a Senior Hiring Manager evaluating a technical interview answer.

Candidate: ${data.candidate_name}

Question Given:
${data.question}

Candidate Answer:
${data.candidate_answer}

EVALUATION RULES:
- If the answer shows deep troubleshooting steps (checking logs, root cause analysis, monitoring, metrics, prevention), give a HIGH score (80-100).
- If the answer is generic, shallow, or only suggests restarting / reinstalling / asking others, give a LOW score (0-50).
- Be objective and base the score only on technical depth.

OUTPUT FORMAT (Indonesian):
**Penilaian untuk ${data.candidate_name}**
-------------------------
🎯 **Skor:** [0-100]
💡 **Analisa:** [Penjelasan singkat 1 kalimat: apakah jawaban menunjukkan kedalaman teknis atau hanya umum]
🚩 **Keputusan:** [LOLOS / GAGAL]
`;

return {
  json: {
    candidate_name: data.candidate_name,
    question: data.question,
    candidate_answer: data.candidate_answer,
    eval_prompt: prompt
  }
};
